1	<!doctype html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>公众号文章检索 · 写过没有</title>
7	<style>
8	:root{
9	  --bg:#faf8f5; --surface:#fffdfb; --line:#e8e2d9; --line-soft:#f0ebe3;
10	  --ink:#1d1a16; --ink-2:#5c554b; --ink-3:#938a7d;
11	  --accent:#0f7264; --accent-soft:#e6f2ef; --accent-ink:#0a5348;
12	  --mark:#fde68a; --mark-ink:#4a3708;
13	  --draft:#b45309; --draft-soft:#fef3e2;
14	  --comic:#8b5cf6; --comic-soft:#f1ecfe;
15	  --radius:14px; --shadow:0 1px 2px rgba(29,26,22,.04),0 8px 24px -12px rgba(29,26,22,.12);
16	}
17	@media (prefers-color-scheme:dark){
18	  :root{
19	    --bg:#141210; --surface:#1c1a17; --line:#2c2823; --line-soft:#242119;
20	    --ink:#f0ece5; --ink-2:#b3aca1; --ink-3:#7d766b;
21	    --accent:#3fb8a3; --accent-soft:#16302c; --accent-ink:#6ed7c3;
22	    --mark:#6b5518; --mark-ink:#ffe9a8;
23	    --draft:#e2a34a; --draft-soft:#2e2317;
24	    --comic:#b79cf7; --comic-soft:#251d3a;
25	    --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px -12px rgba(0,0,0,.6);
26	  }
27	}
28	*{box-sizing:border-box}
29	html,body{margin:0;padding:0}
30	body{
31	  background:var(--bg); color:var(--ink);
32	  font:15px/1.75 -apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;
33	  -webkit-font-smoothing:antialiased;
34	}
35	.wrap{max-width:860px;margin:0 auto;padding:0 20px 80px}
36	
37	/* 顶部 */
38	header{padding:52px 0 24px;transition:padding .3s ease}
39	body.searched header{padding:24px 0 12px}
40	.brand{display:flex;align-items:center;gap:10px;margin-bottom:22px}
41	.brand h1{font-size:21px;font-weight:650;margin:0;letter-spacing:.2px;white-space:nowrap}
42	body.searched .brand{margin-bottom:14px}
43	.brand .sub{color:var(--ink-3);font-size:13px}
44	.brand .grow{flex:1}
45	.hero{font-size:28px;line-height:1.45;font-weight:600;margin:0 0 8px;letter-spacing:-.2px}
46	.hero em{font-style:normal;color:var(--accent);}
47	.hero-note{color:var(--ink-2);margin:0 0 26px;font-size:14.5px}
48	body.searched .hero,body.searched .hero-note{display:none}
49	
50	/* 搜索框 */
51	.searchbar{position:relative;display:flex;align-items:center;gap:14px;
52	  background:var(--surface);border:1.5px solid var(--line);border-radius:30px;
53	  padding:8px 10px 8px 24px;box-shadow:var(--shadow);
54	  transition:border-color .18s,box-shadow .18s}
55	.searchbar:focus-within{border-color:var(--accent);box-shadow:0 0 0 4px var(--accent-soft),var(--shadow)}
56	.searchbar > svg{flex:none;color:var(--ink-3)}
57	#q{flex:1;border:0;outline:0;background:transparent;color:var(--ink);
58	  font-size:19px;line-height:1.4;padding:16px 0;font-family:inherit}
59	#q::placeholder{color:var(--ink-3)}
60	
61	/* 次要动作：一个安静的文字键，别跟箭头抢 */
62	.go.ghost{flex:none;border:0;background:transparent;color:var(--ink-3);
63	  font:500 14.5px/1 inherit;padding:10px 12px;border-radius:999px;cursor:pointer;
64	  transition:color .15s,background .15s}
65	.go.ghost:hover{color:var(--ink);background:var(--accent-soft)}
66	
67	/* 主动作：圆形 + 向右的箭头。左边是放大镜，右边这个是「往前走，拿答案」 */
68	.go.send{flex:none;width:50px;height:50px;padding:0;border:0;border-radius:50%;
69	  background:var(--accent);color:#fff;cursor:pointer;
70	  display:grid;place-items:center;overflow:hidden;
71	  transition:box-shadow .22s cubic-bezier(.2,.7,.3,1),background .18s}
72	.go.send svg{width:21px;height:21px;stroke:currentColor;stroke-width:2.1;
73	  stroke-linecap:round;stroke-linejoin:round;fill:none;
74	  /* 箭头这种形状看着总偏左，往右推一点点才是视觉居中 */
75	  transform:translateX(1px);
76	  transition:transform .22s cubic-bezier(.2,.7,.3,1)}
77	/* 悬停时是箭头自己往前送一下，整个按钮不动——比按钮跳起来安静 */
78	.go.send:hover{box-shadow:0 3px 16px var(--accent-soft)}
79	.go.send:hover svg{transform:translateX(4px)}
80	.go.send:active svg{transform:translateX(2px)}
81	.go:disabled{opacity:.45;cursor:default;transform:none;box-shadow:none}
82	
83	/* 过滤条 */
84	.filters{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px;align-items:center}
85	.chip{border:1px solid var(--line);background:var(--surface);color:var(--ink-2);
86	  border-radius:999px;padding:5px 13px;font-size:13px;cursor:pointer;transition:all .15s;font-family:inherit}
87	.chip:hover{border-color:var(--ink-3)}
88	.chip[aria-pressed="true"]{background:var(--accent);border-color:var(--accent);color:#fff}
89	.filters .spacer{flex:1}
90	.filters .sep{width:1px;height:18px;background:var(--line);margin:0 3px}
91	.meta-line{color:var(--ink-3);font-size:12.5px}
92	
93	/* 例子 */
94	.examples{margin-top:30px}
95	.examples h3{font-size:13px;font-weight:600;color:var(--ink-3);margin:0 0 12px;letter-spacing:.4px}
96	.examples div{display:flex;flex-wrap:wrap;gap:9px}
97	.ex{border:1px dashed var(--line);background:transparent;color:var(--ink-2);border-radius:10px;
98	  padding:8px 13px;font-size:13.5px;cursor:pointer;font-family:inherit;transition:all .15s}
99	.ex:hover{border-style:solid;border-color:var(--accent);color:var(--accent-ink);background:var(--accent-soft)}
100	
101	/* 结果 */
102	#status{color:var(--ink-3);font-size:13.5px;margin:22px 0 14px;min-height:18px}
103	#status.yes{color:var(--accent-ink);font-weight:600}
104	#status.maybe{color:var(--draft);font-weight:600}
105	#status.no{color:var(--ink-2)}
106	.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);
107	  padding:20px 22px;margin-bottom:14px;box-shadow:var(--shadow);
108	  animation:rise .28s cubic-bezier(.2,.7,.3,1) backwards}
109	@keyframes rise{from{opacity:0;transform:translateY(8px)}}
110	.card h2{font-size:17.5px;line-height:1.5;margin:0 0 8px;font-weight:620;letter-spacing:-.1px}
111	.card h2 a{color:var(--ink);text-decoration:none;border-bottom:1.5px solid transparent;transition:.15s}
112	.card h2 a:hover{color:var(--accent-ink);border-bottom-color:var(--accent)}
113	.card h2 span.plain{color:var(--ink)}
114	.tags{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:12.5px;color:var(--ink-3);margin-bottom:12px}
115	.tag{background:var(--line-soft);border-radius:6px;padding:2px 8px;color:var(--ink-2)}
116	.tag.draft{background:var(--draft-soft);color:var(--draft);font-weight:600}
117	.tag.comic{background:var(--comic-soft);color:var(--comic);font-weight:600}
118	/* 漫画缩略图（2026-09-12）：漫画条目只有标题和一行 digest，卡片太空。
119	   原图就在本地，取前三张铺一行，卡片立刻有了分量。 */
120	/* 尺寸挂在 flex 项（<a>）上，不要挂在 <img> 上：<a> 是 flex:0 0 auto 时宽度按内容算，
121	   img 的百分比宽就没有参照物，会掉回原图尺寸把卡片撑爆。踩过一次。 */
122	.thumbs{display:flex;gap:8px;margin:10px 0 2px;justify-content:flex-start}
123	.thumbs a{flex:0 1 104px;max-width:104px;line-height:0}
124	.thumbs img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px;
125	  border:1px solid var(--line);background:var(--soft);display:block}
126	.tag.score{background:var(--line-soft);color:var(--ink-2);font-weight:600;font-variant-numeric:tabular-nums}
127	.tag.score.strong{background:var(--accent-soft);color:var(--accent-ink)}
128	.tag.score.weak{opacity:.62}
129	.snip{color:var(--ink-2);font-size:14.5px;line-height:1.8;margin:0 0 10px;
130	  padding-left:13px;border-left:2px solid var(--line)}
131	.snip .h{display:block;font-size:12px;color:var(--ink-3);margin-bottom:3px}
132	mark{background:var(--mark);color:var(--mark-ink);border-radius:3px;padding:0 2px}
133	.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}
134	.btn{border:1px solid var(--line);background:transparent;color:var(--ink-2);border-radius:9px;
135	  padding:7px 13px;font-size:13px;cursor:pointer;font-family:inherit;
136	  display:inline-flex;align-items:center;gap:6px;transition:all .15s}
137	.btn:hover{border-color:var(--accent);color:var(--accent-ink);background:var(--accent-soft)}
138	.btn.primary{border-color:var(--accent);color:#fff;background:var(--accent)}
139	.btn.primary:hover{opacity:.88;color:#fff}
140	.btn.done{border-color:var(--accent);background:var(--accent);color:#fff}
141	#answer{background:var(--card);border:1px solid var(--line);border-radius:14px;
142	  padding:18px 20px 14px;margin:0 0 18px;box-shadow:0 1px 2px rgba(20,40,30,.04)}
143	#answer .ans-body{font-size:15.5px;line-height:1.85;color:var(--ink);white-space:pre-wrap}
144	#answer .ans-body .cite{display:inline-block;min-width:17px;height:17px;line-height:17px;
145	  margin:0 1px;padding:0 4px;border-radius:5px;background:#e7f0ea;color:var(--accent);
146	  font-size:11px;font-weight:700;text-align:center;cursor:pointer;vertical-align:2px;user-select:none}
147	#answer .ans-body .cite:hover{background:var(--accent);color:#fff}
148	#answer .ans-body .err{color:#b4472e}
149	#answer .src{margin-top:14px;padding-top:11px;border-top:1px dashed var(--line);
150	  display:flex;flex-wrap:wrap;gap:6px 14px;align-items:baseline;font-size:12.5px}
151	#answer .src span{color:var(--dim)}
152	#answer .src a{color:var(--accent);text-decoration:none}
153	#answer .src a:hover{text-decoration:underline}
154	#answer .nokey{font-size:14px;line-height:1.8;color:var(--ink)}
155	#answer .nokey b{display:block;margin-bottom:6px}
156	#answer .nokey ol{margin:8px 0 6px;padding-left:22px}
157	#answer .nokey li{margin:3px 0}
158	#answer .nokey code{background:#eef2ef;padding:1px 5px;border-radius:4px;font-size:12.5px}
159	#answer .nokey a{color:var(--accent)}
160	button:disabled{opacity:.5;cursor:not-allowed}
161	.go.unconfigured{background:#9aa7a0}
162	#answer .ans-foot{margin-top:12px;padding-top:10px;border-top:1px solid var(--line);
163	  font-size:12px;color:var(--muted)}
164	#answer.thinking .ans-body::after{content:"\258D";color:var(--accent);animation:blink 1s steps(2) infinite}
165	@keyframes blink{50%{opacity:0}}
166	.card.cited{border-color:var(--accent);box-shadow:0 0 0 3px #e7f0ea}
167	button.ghost{background:transparent;color:var(--muted);border:1px solid var(--line)}
168	button.ghost:hover{color:var(--ink);border-color:var(--muted)}
169	#stale{position:sticky;top:0;z-index:9;background:var(--accent);color:#fff;
170	  padding:9px 16px;font-size:13.5px;display:flex;gap:12px;align-items:center;justify-content:center}
171	#stale button{background:#fff;color:var(--accent);border:none;border-radius:5px;
172	  padding:3px 12px;font-size:13px;cursor:pointer;font-weight:600}
173	.fulltext .ft-h{display:block;color:var(--ink);font-weight:650;margin:16px 0 2px;font-size:14px}
174	.fulltext .ft-h:first-child{margin-top:0}
175	.fulltext{margin-top:14px;padding-top:14px;border-top:1px dashed var(--line);
176	  white-space:pre-wrap;font-size:14.5px;line-height:1.85;color:var(--ink-2);
177	  max-height:460px;overflow:auto}
178	.empty{text-align:center;color:var(--ink-3);padding:56px 20px;font-size:14.5px}
179	
180	/* 复制提示 */
181	#toast{position:fixed;left:50%;bottom:34px;transform:translate(-50%,14px);
182	  background:var(--ink);color:var(--bg);padding:10px 18px;border-radius:10px;font-size:13.5px;
183	  opacity:0;pointer-events:none;transition:all .22s;z-index:9}
184	#toast.show{opacity:1;transform:translate(-50%,0)}
185	footer{margin-top:34px;color:var(--ink-3);font-size:12px;text-align:center;line-height:1.9}
186	
187	body.graphing .hero,body.graphing .hero-note,body.graphing .searchbar,
188	body.graphing .filters,body.graphing .examples,body.graphing #status,
189	body.graphing #answer,body.graphing #results{display:none}
190	body.graphing .wrap{max-width:1120px}
191	body.graphing header{padding:28px 0 8px}
192	#graph-panel{margin-top:8px}
193	.graph-toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:12px}
194	#gq{flex:1;min-width:160px;border:1px solid var(--line);background:var(--surface);color:var(--ink);
195	  border-radius:999px;padding:7px 14px;font:13.5px inherit;outline:0}
196	#gq:focus{border-color:var(--accent)}
197	.graph-stage{display:grid;grid-template-columns:1fr 280px;gap:14px;align-items:stretch}
198	@media (max-width:820px){.graph-stage{grid-template-columns:1fr}}
199	#gcanvas{width:100%;height:620px;background:var(--surface);border:1px solid var(--line);
200	  border-radius:var(--radius);box-shadow:var(--shadow);cursor:grab;touch-action:none}
201	#gcanvas:active{cursor:grabbing}
202	#ginfo{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);
203	  padding:16px 16px 14px;box-shadow:var(--shadow);min-height:200px}
204	#ginfo h3{margin:0 0 6px;font-size:16px;line-height:1.45}
205	#ginfo h3 a{color:var(--ink);text-decoration:none}
206	#ginfo h3 a:hover{color:var(--accent-ink)}
207	#ginfo .gmeta{color:var(--ink-3);font-size:12.5px;margin:0 0 12px}
208	#ginfo .gsec{font-size:12px;color:var(--ink-3);margin:12px 0 6px;font-weight:600}
209	#ginfo .gn{display:block;width:100%;text-align:left;border:0;background:transparent;
210	  color:var(--ink-2);font:13.5px/1.55 inherit;padding:4px 0;cursor:pointer}
211	#ginfo .gn:hover{color:var(--accent-ink)}
212	#ginfo .ghint{color:var(--ink-3);font-size:13.5px;margin:0;line-height:1.7}
213	.graph-legend{color:var(--ink-3);font-size:12.5px;margin:10px 0 0}
214	</style>
215	</head>
216	<body>
217	<div class="wrap">
218	  <header>
219	    <div class="brand">
220	      <h1>写过没有</h1>
221	      <span class="sub">公众号文章语义检索</span>
222	    </div>
223	    <p class="hero">这个观点，我<em>以前写过吗</em>？</p>
224	    <p class="hero-note">按意思搜，不用记标题。搜到了直接把链接复制走。</p>
225	
226	    <div class="searchbar">
227	      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
228	        <circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/>
229	      </svg>
230	      <input id="q" placeholder="比如：AI 写的代码要不要逐行看" autocomplete="off" autofocus>
231	      <button class="go send" id="ask" title="问一句" aria-label="问一句">
232	        <svg viewBox="0 0 24 24"><path d="M5.5 12h12M12.4 7l5.1 5-5.1 5"/></svg>
233	      </button>
234	    </div>
235	
236	    <div class="filters">
237	      <button class="chip" data-kind="all" aria-pressed="true">文章 + 漫画</button>
238	      <button class="chip" data-kind="article" aria-pressed="false">只看文章</button>
239	      <button class="chip" data-kind="comic" aria-pressed="false">只看漫画</button>
240	      <button class="chip" data-kind="file" aria-pressed="false">我的文件</button>
241	      <span class="spacer"></span>
242	      <button class="chip" data-order="relevance" aria-pressed="true">按相关度</button>
243	      <button class="chip" data-order="date" aria-pressed="false">按时间</button>
244	    </div>
245	    <div class="meta-line" id="stats"></div>
246	  </header>
247	
248	  <div class="examples" id="examples">
249	    <h3>随便试试</h3>
250	    <div>
251	      <button class="ex">AI 写的代码要不要逐行 review</button>
252	      <button class="ex">怎么省 token</button>
253	      <button class="ex">让 AI 查数据库为什么不准</button>
254	      <button class="ex">缓存不是性能优化的答案</button>
255	      <button class="ex">带学员怎么教才有效</button>
256	      <button class="ex">上了 K8s 就算云原生吗</button>
257	      <button class="ex">杀猪盘怎么套人</button>
258	      <button class="ex">孩子学不会是我讲错了</button>
259	    </div>
260	  </div>
261	
262	  <div id="status"></div>
263	  <div id="answer" hidden>
264	    <div class="ans-body"></div>
265	    <div class="ans-foot">上面每句话都出自下面这几篇，点角标跳到出处。</div>
266	  </div>
267	  <div id="results"></div>
268	  <div id="graph-panel" hidden>
269	    <div class="graph-toolbar">
270	      <input id="gq" placeholder="在图里找一篇…" autocomplete="off">
271	      <button class="chip" data-gedge="all" aria-pressed="true">全部关系</button>
272	      <button class="chip" data-gedge="cite" aria-pressed="false">只看互链</button>
273	      <span class="sep"></span>
274	      <button class="chip" data-gkind="all" aria-pressed="true">文章+漫画</button>
275	      <button class="chip" data-gkind="article" aria-pressed="false">只看文章</button>
276	      <button class="chip" data-gkind="comic" aria-pressed="false">只看漫画</button>
277	    </div>
278	    <div class="graph-stage">
279	      <canvas id="gcanvas"></canvas>
280	      <aside id="ginfo"><p class="ghint">点一篇，看它引用了谁、题义上挨着谁。滚轮缩放，拖空白处平移。</p></aside>
281	    </div>
282	    <p class="graph-legend">颜色是主题簇。实线是文里点名引用；点一篇才画出题义接近的虚线。</p>
283	  </div>
284	  <footer id="foot"></footer>
285	</div>
286	<div id="toast"></div>
287	
288	<script>
289	const $ = s => document.querySelector(s);
290	const qEl = $('#q'), resEl = $('#results'), statusEl = $('#status');
291	let order = 'relevance', kind = 'all', mode = 'hybrid', terms = [], seq = 0, canAnswer = true;
292	let startedAt = null;
293	
294	// 改完代码重启服务，开着的页面还跑着旧 JS——看着就像「改了没生效」。
295	// 服务每次响应都带自己的启动时刻，跟页面记下的对不上就摆条提示。
296	function noteServerRestart(ts){
297	  if (!ts) return;
298	  if (startedAt === null){ startedAt = ts; return; }
299	  if (ts === startedAt || document.querySelector('#stale')) return;
300	  const bar = document.createElement('div');
301	  bar.id = 'stale';
302	  bar.innerHTML = `服务重启过了，这个页面还是旧版本。<button>刷新一下</button>`;
303	  bar.querySelector('button').onclick = () => location.reload();
304	  document.body.prepend(bar);
305	}
306	
307	{ const m = new URLSearchParams(location.search).get('mode'); if (m === 'vector' || m === 'lex') mode = m; }
308	fetch('/api/stats').then(r => r.json()).then(s => {
309	  $('#stats').textContent =
310	    (canAnswer = s.can_answer !== false, markAskDisabled(),
311	     `${s.articles - s.comics - (s.files || 0)} 篇文章 + ${s.comics} 篇漫画 · ${s.earliest.slice(0,4)}–${s.latest.slice(0,4)} · 篇篇能点开原文`
312	     + (s.files ? ` · 我的文件 ${s.files} 份` : '')
313	     + (mode !== 'hybrid' ? ` · 检索方式：${mode === 'vector' ? '只用向量（按意思）' : '只用字面（按字）'}` : ''));
314	  $('#foot').textContent = `检索在本机跑：向量模型 ${s.model}，索引建于 ${s.built_at}`
315	    + (s.can_answer === false ? ' · 未配回答模型' : ' · 已接模型');
316	});
317	
318	document.querySelectorAll('.filters .chip').forEach(chip => chip.onclick = () => {
